# Generated by build.py from recipe.yml for recipe ftp-choose-passive-or-active-mode. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/passive.txt'), "fetched passive`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/active.txt'), "fetched active`n")
$server0 = Start-Process surl -ArgumentList '-v', '--directory', 'site', '--allow-anonymous', '--log-file', 'site/surl.log', 'ftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -v --disable-epsv ftp://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
